import {VisPluginTableModel} from './vis_table_plugin';
import * as d3 from './d3loader';
import themeTraditional from './theme_traditional.css';
import themeLooker from './theme_looker.css';
import themeContemporary from './theme_contemporary.css';
import layoutFixed from './layout_fixed.css';
import layoutAuto from './layout_auto.css';

const themes = {
  traditional: themeTraditional,
  looker: themeLooker,
  contemporary: themeContemporary,

  fixed: layoutFixed,
  auto: layoutAuto,
};

const BBOX_X_ADJUST = 10;
const BBOX_Y_ADJUST = 10;

const use_minicharts = false;

const removeStyles = async function () {
  const links = document.getElementsByTagName('link');
  while (links[0]) links[0].parentNode.removeChild(links[0]);

  Object.keys(themes).forEach(async theme => await themes[theme].unuse());
};

const loadStylesheet = function (link) {
  const linkElement = document.createElement('link');

  linkElement.setAttribute('rel', 'stylesheet');
  linkElement.setAttribute('href', link);

  document.getElementsByTagName('head')[0].appendChild(linkElement);
};

const buildReportTable = async function (
  config,
  dataTable,
  updateColumnOrder,
  element,
  details
) {
  var dropTarget = null;
  const bounds = element.getBoundingClientRect();
  const chartCentreX = bounds.x + bounds.width / 2;
  const chartCentreY = bounds.y + bounds.height / 2;

  await removeStyles();
  if (
    typeof config.customTheme !== 'undefined' &&
    config.customTheme &&
    config.theme === 'custom'
  ) {
    loadStylesheet(config.customTheme);
  } else if (typeof themes[config.theme] !== 'undefined') {
    themes[config.theme].use();
  }
  if (typeof themes[config.layout] !== 'undefined') {
    themes[config.layout].use();
  }

  // Sort group based on sort order from looker
  const sortByColumnSeries = function (group) {
    // transposing interim fix...if transpose is ON, then return group
    // dataTable.column_series would be undefined in this case
    if (dataTable.transposeTable) {
      return group;
    }

    // Get sort order from column series
    const columnSeriesOrder = (dataTable.column_series || []).map(
      col => col.column.id
    );

    // Build new array of group data in same order as column_series
    const orderedGroup = [];
    columnSeriesOrder.forEach(colName => {
      group.forEach(group => {
        // colName will never equal group.id
        if (colName === group.id) {
          orderedGroup.push(group);
        }
      });
    });
    return orderedGroup;
  };

  const renderTable = async function () {
    const getTextWidth = function (text, font = '') {
      // re-use canvas object for better performance
      var canvas =
        getTextWidth.canvas ||
        (getTextWidth.canvas = document.createElement('canvas'));
      var context = canvas.getContext('2d');
      context.font = font || config.bodyFontSize + 'pt arial';
      var metrics = context.measureText(text);
      return metrics.width;
    };

    var table = d3
      .select(element)
      .select('#visContainer')
      .append('table')
      .attr('id', 'reportTable')
      .attr('class', 'reportTable')
      .style('opacity', 0);

    var drag = d3
      .drag()
      .on('start', (event, source) => {
        if (!dataTable.has_pivots && source.colspan === 1) {
          // if a headercell is a merged cell, can't tell which column its associated with
          var xPosition = parseFloat(event.x);
          var yPosition = parseFloat(event.y);
          var html = source.column.getHeaderCellLabelByType('field');

          d3.select(element)
            .select('#tooltip')
            .style('left', xPosition + 'px')
            .style('top', yPosition + 'px')
            .html(html);

          d3.select(element).select('#tooltip').classed('hidden', false);
        }
      })
      .on('drag', (event, source) => {
        if (!dataTable.has_pivots) {
          d3.select(element)
            .select('#tooltip')
            .style('left', event.x + 'px')
            .style('top', event.y + 'px');
        }
      })
      .on('end', (event, source) => {
        if (!dataTable.has_pivots) {
          d3.select(element).select('#tooltip').classed('hidden', true);
          if (dropTarget && dropTarget.column) {
            var movingColumn = source.column;
            var targetColumn = dropTarget.column;
            var movingIdx = Math.floor(movingColumn.pos / 10) * 10;
            var targetIdx = Math.floor(targetColumn.pos / 10) * 10;
            dataTable.moveColumns(movingIdx, targetIdx, updateColumnOrder);
          }
        }
      });

    if (dataTable.minWidthForIndexColumns) {
      var columnTextWidths = {};

      if (!dataTable.transposeTable) {
        dataTable.column_series
          .filter(cs => !cs.column.hide)
          .filter(cs => cs.column.modelField.type === 'dimension')
          .forEach(cs => {
            var maxLength = cs.series.values.reduce((a, b) =>
              Math.max(getTextWidth(a), getTextWidth(b))
            );
            var columnId = cs.column.modelField.name;
            if (dataTable.useIndexColumn) {
              columnId = '$$$_index_$$$';
              maxLength += 15;
            }
            columnTextWidths[columnId] = Math.ceil(maxLength);
          });
      } else {
        dataTable.headers.forEach(header => {
          var fontSize = 'bold ' + config.bodyFontSize + 'pt arial';
          var maxLength = dataTable.transposed_data
            .map(row => row.data[header.type].rendered)
            .reduce((a, b) =>
              Math.max(getTextWidth(a, fontSize), getTextWidth(b, fontSize))
            );
          columnTextWidths[header.type] = Math.ceil(maxLength);
        });
      }
    }

    var column_groups = table
      .selectAll('colgroup')
      .data(dataTable.getTableColumnGroups())
      .enter()
      .append('colgroup');

    column_groups
      .selectAll('col')
      .data(d => d)
      .enter()
      .append('col')
      .attr('id', d => ['col', d.id].join('').replace('.', ''))
      .attr('span', 1)
      .style('width', d => {
        if (
          dataTable.minWidthForIndexColumns &&
          d.type === 'index' &&
          typeof columnTextWidths[d.id] !== 'undefined'
        ) {
          return columnTextWidths[d.id] + 'px';
        } else {
          return '';
        }
      });

    var header_rows = table
      .append('thead')
      .selectAll('tr')
      .data(dataTable.getHeaderTiers())
      .enter();

    var header_cells = header_rows
      .append('tr')
      .selectAll('th')
      .data((level, i) =>
        dataTable.getTableHeaderCells(i).map(column => column.levels[i])
      )
      .enter();

    header_cells
      .append('th')
      .text(d => d.label)
      .attr('id', d => d.id)
      .attr('colspan', d => d.colspan)
      .attr('rowspan', d => d.rowspan)
      .attr('class', d => {
        var classes = ['reportTable'];
        if (typeof d.cell_style !== 'undefined') {
          classes = classes.concat(d.cell_style);
        }
        return classes.join(' ');
      })
      .style('text-align', 'left')
      .style('font-size', config.headerFontSize + 'px')
      .attr('draggable', true)
      .call(drag)
      .on('mouseover', (event, cell) => {
        d3.select(element)
          .select('#tooltip')
          .style('left', event.x + 'px')
          .style('top', event.y + 'px')
          .html(cell.label);
        d3.select(element).select('#tooltip').classed('hidden', false);
        return (dropTarget = cell);
      })
      .on('mouseout', (event, cell) => {
        d3.select(element).select('#tooltip').classed('hidden', true);
        return (dropTarget = null);
      });

    var table_rows = table
      .append('tbody')
      .selectAll('tr')
      .data(dataTable.getDataRows())
      .enter()
      .append('tr')
      .on('mouseover', function () {
        if (dataTable.showHighlight) {
          this.classList.toggle('hover');
        }
      })
      .on('mouseout', function () {
        if (dataTable.showHighlight) {
          this.classList.toggle('hover');
        }
      })
      .selectAll('td')
      .data(row =>
        dataTable.getTableRowColumns(row).map(column => row.data[column.id])
      )
      .enter();

    table_rows
      .append('td')
      .text(d => {
        var text = '';
        if (Array.isArray(d.value)) {
          // cell is a list or number_list
          text = !(d.rendered === null) ? d.rendered : d.value.join(' ');
        } else if (
          typeof d.value === 'object' &&
          d.value !== null &&
          typeof d.value.series !== 'undefined'
        ) {
          // cell is a turtle
          text = null;
        } else if (d.html) {
          // cell has HTML defined
          var parser = new DOMParser();
          var parsed_html = parser.parseFromString(d.html, 'text/html');
          text = parsed_html.documentElement.textContent;
        } else if (d.rendered || d.rendered === '') {
          // could be deliberate choice to render empty string
          text = d.rendered;
        } else {
          text = d.value;
        }
        text = String(text);
        return text ? text.replace('-', '\u2011') : text; // prevents wrapping on minus sign / hyphen
      })
      .attr('rowspan', d => d.rowspan)
      .attr('colspan', d => d.colspan)
      .style('text-align', d => d.align)
      .style('font-size', config.bodyFontSize + 'px')
      .attr('class', d => {
        var classes = ['reportTable'];
        if (typeof d.value === 'object') {
          classes.push('cellSeries');
        }
        if (typeof d.align !== 'undefined') {
          classes.push(d.align);
        }
        if (typeof d.cell_style !== 'undefined') {
          classes = classes.concat(d.cell_style);
        }
        return classes.join(' ');
      })
      .on('mouseover', (event, d) => {
        if (dataTable.showHighlight) {
          if (!dataTable.transposeTable) {
            var id = ['col', d.colid].join('').replace('.', '');
          } else {
            var id = ['col', d.rowid].join('').replace('.', '');
          }

          var colElement = element.querySelector('#' + id);
          if (colElement) {
            colElement.classList.toggle('hover');
          }
        }

        if (dataTable.showTooltip && d.cell_style.includes('measure')) {
          var x = event.clientX;
          var y = event.clientY;
          var html = dataTable.getCellToolTip(d.rowid, d.colid);

          d3.select(element)
            .select('#tooltip')
            .style('left', x + 'px')
            .style('top', y + 'px')
            .html(html);

          d3.select(element).select('#tooltip').classed('hidden', false);
        }
      })
      .on('mousemove', (event, d) => {
        if (dataTable.showTooltip && d.cell_style.includes('measure')) {
          var tooltip = d3.select(element).select('#tooltip');
          var x =
            event.clientX < chartCentreX
              ? event.pageX + 10
              : event.pageX - tooltip.node().getBoundingClientRect().width - 10;
          var y =
            event.clientY < chartCentreY
              ? event.pageY + 10
              : event.pageY -
                tooltip.node().getBoundingClientRect().height -
                10;

          tooltip.style('left', x + 'px').style('top', y + 'px');
        }
      })
      .on('mouseout', (event, d) => {
        if (dataTable.showHighlight) {
          if (!dataTable.transposeTable) {
            var id = ['col', d.colid].join('').replace('.', '');
          } else {
            var id = ['col', d.rowid].join('').replace('.', '');
          }
          var colElement = element.querySelector('#' + id);
          if (colElement) {
            colElement.classList.toggle('hover');
          }
        }

        if (dataTable.showTooltip && d.cell_style.includes('measure')) {
          d3.select(element).select('#tooltip').classed('hidden', true);
        }
      })
      .on('click', (event, d) => {
        if (d.links && d.links.length > 0 && d.links[0].url) {
          let evt = {
            metaKey: event.metaKey,
            pageX: event.pageX,
            pageY: event.pageY - window.pageYOffset,
          };
          if (
            typeof LookerCharts !== 'undefined' &&
            LookerCharts.Utils?.openDrillMenu
          ) {
            LookerCharts.Utils.openDrillMenu({
              links: d.links,
              event: evt,
            });
          }
        }
      });

    if (use_minicharts) {
      var barHeight = 16;
      var minicharts = table
        .selectAll('.cellSeries')
        .append('svg')
        .attr('height', d => barHeight)
        .attr('width', '100%')
        .append('g')
        .attr('class', '.cellSeriesChart')
        .selectAll('rect')
        .data(d => {
          var values = [];
          for (var i = 0; i < d.value.series.keys.length; i++) {
            values.push({
              idx: i,
              max: 10000,
              key: d.value.series.keys[i],
              value: d.value.series.values[i],
              type: d.value.series.types[i],
            });
          }
          return values.filter(value => value.type === 'line_item');
        })
        .enter();

      var cellWidth = table.selectAll('.cellSeries')._groups[0][0].clientWidth;
      var barWidth = Math.floor(cellWidth / 10);

      minicharts
        .append('rect')
        .style('fill', 'steelblue')
        .attr('x', value => value.idx * barWidth)
        .attr(
          'y',
          value => barHeight - Math.floor((value.value / value.max) * barHeight)
        )
        .attr('width', barWidth)
        .attr('height', value =>
          Math.floor((value.value / value.max) * barHeight)
        );
    }
  };

  const addOverlay = async function (details) {
    const isPrint = Boolean(details?.print);
    const duration = isPrint ? 0 : 1000;

    const reportTableEl = element.querySelector('#reportTable');
    var viewbox_width = reportTableEl
      ? reportTableEl.clientWidth
      : element.clientWidth;
    var viewbox_height = reportTableEl
      ? reportTableEl.clientHeight
      : element.clientHeight;

    var allRects = [];
    d3.select(element)
      .selectAll('th')
      .select(function (d, i) {
        if (typeof d !== 'undefined') {
          var bbox = this.getBoundingClientRect();
          allRects.push({
            index: i,
            data: d,
            x: bbox.x - BBOX_X_ADJUST,
            y: bbox.y - BBOX_Y_ADJUST,
            width: bbox.width,
            height: bbox.height,
            html: this.innerHTML,
            class: this.className + ' rectElem animated',
            fontSize: config.headerFontSize,
            align: this.style.textAlign,
          });
        }
      });

    d3.select(element)
      .selectAll('td')
      .select(function (d, i) {
        if (typeof d !== 'undefined') {
          var bbox = this.getBoundingClientRect();
          allRects.push({
            index: i,
            data: d,
            x: bbox.x - BBOX_X_ADJUST,
            y: bbox.y - BBOX_Y_ADJUST,
            width: bbox.width,
            height: bbox.height,
            html: this.innerHTML,
            class: this.className + ' rectElem animated',
            fontSize: config.bodyFontSize,
            align: this.style.textAlign,
          });
        }
      });

    var overlay = d3
      .select(element)
      .select('#visSvg')
      .attr('width', viewbox_width)
      .attr('height', viewbox_height)
      .selectAll('.rectElem')
      .data(allRects, d => d.data.id)
      .join(
        enter =>
          enter
            .append('div')
            .attr('class', d => d.class)
            .style('opacity', isPrint ? 1 : 0.2)
            .style('position', 'absolute')
            .style('left', d => d.x + 'px')
            .style('top', d => (isPrint ? d.y + 'px' : -2000))
            .style('width', d => d.width + 'px')
            .style('height', d => d.height + 'px')
            .style('font-size', d => d.fontSize + 'px')
            .style('text-align', d => d.align)
            .text(d => d.html)
            .call(enter => {
              if (isPrint) {
                return enter.style('opacity', 1).style('top', d => d.y + 'px');
              } else {
                return enter
                  .transition()
                  .duration(duration)
                  .style('opacity', 1)
                  .style('top', d => d.y + 'px');
              }
            }),
        update =>
          update.call(update => {
            if (isPrint) {
              return update
                .attr('class', d => d.class)
                .style('opacity', 1)
                .style('left', d => d.x + 'px')
                .style('top', d => d.y + 'px')
                .style('width', d => d.width + 'px')
                .style('height', d => d.height + 'px')
                .style('font-size', d => d.fontSize + 'px')
                .style('text-align', d => d.align)
                .text(d => d.html);
            } else {
              return update
                .transition()
                .duration(duration)
                .attr('class', d => d.class)
                .style('opacity', 1)
                .style('left', d => d.x + 'px')
                .style('top', d => d.y + 'px')
                .style('width', d => d.width + 'px')
                .style('height', d => d.height + 'px')
                .style('font-size', d => d.fontSize + 'px')
                .style('text-align', d => d.align)
                .text(d => d.html);
            }
          }),
        exit =>
          exit.call(exit => {
            if (isPrint) {
              return exit.remove();
            } else {
              return exit
                .transition()
                .duration(500)
                .style('opacity', 0)
                .remove();
            }
          })
      );

    if (!isPrint && overlay.transition) {
      try {
        if (typeof d3.timerFlush === 'function') {
          d3.timerFlush();
        }
        await overlay.transition().end();
      } catch (err) {
        // Transition interrupted or completed
      }
    }
  };

  await renderTable();
  try {
    const reportTableEl = element.querySelector('#reportTable');
    if (reportTableEl) {
      reportTableEl.classList.add('reveal');
    }
    const visSvgEl = element.querySelector('#visSvg');
    if (config.customTheme === 'animate') {
      if (visSvgEl) visSvgEl.classList.remove('hidden');
      await addOverlay(details);
    } else {
      if (visSvgEl) visSvgEl.classList.add('hidden');
      if (reportTableEl) reportTableEl.style.opacity = 1;
    }
  } catch (err) {
    console.error('Error revealing report table:', err);
  }
};

looker.plugins.visualizations.add({
  options: VisPluginTableModel.getCoreConfigOptions(),

  create: function (element, config) {
    element.innerHTML = ''; // Ensure clean slate when Looker re-uses the container

    this.svgContainer = d3
      .select(element)
      .append('div')
      .attr('id', 'visSvg')
      .attr('width', element.clientWidth)
      .attr('height', element.clientHeight);

    this.tooltip = d3
      .select(element)
      .append('div')
      .attr('id', 'tooltip')
      .attr('class', 'hidden');
  },

  updateAsync: async function (
    data,
    element,
    config,
    queryResponse,
    details,
    done
  ) {
    const updateColumnOrder = newOrder => {
      this.trigger('updateConfig', [{columnOrder: newOrder}]);
    };

    try {
      // ERROR HANDLING
      this.clearErrors();

      // empty pivot(s)...no measures
      if (
        queryResponse?.fields?.pivots?.length > 0 &&
        queryResponse?.fields?.measure_like?.length === 0
      ) {
        this.addError({
          title: 'Empty Pivot(s)',
          message: 'Add a measure or table calculation to pivot on.',
        });
        return;
      }

      // max pivot check
      if (queryResponse?.fields?.pivots?.length > 2) {
        this.addError({
          title: 'Max Two Pivots',
          message: 'This visualization accepts no more than 2 pivot fields.',
        });
        return;
      }

      // Check for results
      if (!data || !data.length) {
        this.addError({
          title: 'No Results',
          message: 'The query returned no data.',
        });
        return;
      }

      // Check for valid fields to prevent TableModel crashes
      if (
        !queryResponse.fields ||
        (queryResponse.fields.dimension_like?.length === 0 &&
          queryResponse.fields.measure_like?.length === 0)
      ) {
        this.addError({
          title: 'No Fields',
          message: 'Please add at least one dimension or measure.',
        });
        return;
      }

      // INITIALISE THE VIS
      try {
        var elem = element.querySelector('#visContainer');
        if (elem) {
          elem.parentNode.removeChild(elem);
        }
      } catch (e) {
        console.warn('Could not remove #visContainer', e);
      }

      this.container = d3
        .select(element)
        .append('div')
        .attr('id', 'visContainer');

      if (typeof config.columnOrder === 'undefined') {
        config.columnOrder = {};
        this.trigger('updateConfig', [{columnOrder: {}}]);
      }

      // Dashboard-next fails to register config if no one has touched it
      // Check to reapply default settings to the config object
      if (typeof config.theme === 'undefined') {
        config = Object.assign(
          {
            bodyFontSize: 12,
            headerFontSize: 12,
            theme: 'traditional',
            showHighlight: true,
            showTooltip: true,
          },
          config
        );
      }

      // BUILD THE VIS
      var dataTable = new VisPluginTableModel(data, queryResponse, config);
      this.trigger('registerOptions', dataTable.getConfigOptions());

      await buildReportTable(
        config,
        dataTable,
        updateColumnOrder,
        element,
        details
      );
    } catch (error) {
      console.error('Visualization Update Error:', error);
      this.addError({
        title: 'Rendering Error',
        message: 'Failed to draw the table.',
      });
    } finally {
      if (typeof done === 'function') {
        done();
      }
    }
  },
});
